/* ==========================================================================
   GENERADOR Y DESCARGA DIRECTA DE CV EN FORMATO PDF OPTIMIZADO PARA ATS E IA
   Archivo: Josseph_Steven_Bolsios_Cortes_CV_ATS.pdf
   Incluye capa vectorial 100% seleccionable + capa semántica estructurada JSON-LD / ATS
   ========================================================================== */
(function () {
  var ATS_PDF_BASE64 = "";

  window.downloadATSCV = function (e) {
    if (e && e.preventDefault) e.preventDefault();
    try {
      var byteChars = atob(ATS_PDF_BASE64);
      var byteNumbers = new Array(byteChars.length);
      for (var i = 0; i < byteChars.length; i++) {
        byteNumbers[i] = byteChars.charCodeAt(i);
      }
      var byteArray = new Uint8Array(byteNumbers);
      var blob = new Blob([byteArray], { type: 'application/pdf' });
      var blobUrl = URL.createObjectURL(blob);

      var a = document.createElement('a');
      a.style.display = 'none';
      a.href = blobUrl;
      a.download = 'Josseph_Steven_Bolsios_Cortes_CV_ATS.pdf';
      document.body.appendChild(a);
      a.click();

      setTimeout(function () {
        document.body.removeChild(a);
        URL.revokeObjectURL(blobUrl);
      }, 1500);
    } catch (err) {
      window.open('Media/Josseph_Bolsios_CV_ATS.pdf', '_blank');
    }
  };

  document.addEventListener('DOMContentLoaded', function () {
    var cvLinks = document.querySelectorAll('a[download], a[href*="cv.png"], a[href*="Josseph_Bolsios_CV"], .js-download-cv');
    cvLinks.forEach(function (link) {
      link.setAttribute('href', 'Media/Josseph_Bolsios_CV_ATS.pdf');
      link.setAttribute('download', 'Josseph_Steven_Bolsios_Cortes_CV_ATS.pdf');
      link.addEventListener('click', function (ev) {
        window.downloadATSCV(ev);
      });
    });
  });
})();
